                dict(label='Denuncia', points=[dict(text='La vaca va al matadero «para comer los señores, los curas... los indianos»: critica la desigualdad; en la segunda parte, Pinín es carne de cañón en la guerra carlista, sin conocer las ideas por las que lucha.', quotes=[Q('ws_cordera', 'para convertirla en manjares de ricos glotones'), Q('es_naturalismo', 'Sátira y denuncia social.')])]),
