                dict(label='Ironía', points=[dict(text='La torre «se pone en jarras» y el santo «danzante»: la personificación humoriza lo sagrado con tono irónico.', quotes=[Q('ws_misericordia', 'de la cual podría creerse que se pone en jarras'), Q('ws_misericordia', 'más bien danzante que religiosa')])]),
                dict(label='Espacio y sociedad', points=[dict(text='Las dos fachadas enfrentan los barrios bajos con el señorío mercantil: el espacio es una radiografía social.', quotes=[Q('ws_misericordia', 'con la una mira a los barrios bajos'), Q('es_realismo', 'Las obras muestran una relación inmediata entre las personas y su entorno económico y social')])]),
